+             */
+            if (phdr.has_channel) {
+                if (CHAN_IS_BG(phdr.channel)) {
+                    /* 11g */
+                    phdr.phy = PHDR_802_11_PHY_11G;
+                }
+            }
+            if (RATE_IS_DSSS(phdr.data_rate)) {
+                /* DSSS, so 11b. */
